import React, { useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

// Fix for default marker icons in react-leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png'
});

const LocationMap = ({ latitude, longitude, area, isExpanded = false }) => {
  const [showExpanded, setShowExpanded] = useState(false);

  // Default to Dhaka if coordinates not provided
  const lat = latitude || 23.8103;
  const lng = longitude || 90.4167;

  const containerHeight = isExpanded || showExpanded ? 'h-96' : 'h-48';

  const MapContent = () => (
    <MapContainer
      center={[lat, lng]}
      zoom={isExpanded || showExpanded ? 15 : 13}
      style={{ height: '100%', width: '100%' }}
      zoomControl={isExpanded || showExpanded}
    >
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      />
      <Marker position={[lat, lng]}>
        <Popup>
          <div className="text-sm font-semibold">
            <p>Crime Location</p>
            <p className="text-xs text-gray-600 mt-1">{area || 'Unknown Area'}</p>
            <p className="text-xs text-gray-600">{lat.toFixed(4)}, {lng.toFixed(4)}</p>
          </div>
        </Popup>
      </Marker>
    </MapContainer>
  );

  // Expanded modal view
  if (showExpanded) {
    return (
      <>
        <div className="fixed inset-0 bg-black bg-opacity-50 z-40" onClick={() => setShowExpanded(false)} />
        <div className="fixed inset-4 md:inset-8 bg-white rounded-2xl shadow-2xl z-50 flex flex-col animate-fadeIn">
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-gray-200">
            <div>
              <h2 className="text-2xl font-bold text-gray-900">Crime Location</h2>
              <p className="text-sm text-gray-600 mt-1">📍 {area || 'Unknown Area'}</p>
              <p className="text-xs text-gray-500 mt-1">Coordinates: {lat.toFixed(6)}, {lng.toFixed(6)}</p>
            </div>
            <button
              onClick={() => setShowExpanded(false)}
              className="text-gray-500 hover:text-gray-700 transition-colors"
            >
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* Map */}
          <div className="flex-1 relative">
            <MapContent />
          </div>

          {/* Footer */}
          <div className="px-6 py-4 border-t border-gray-200 flex justify-between items-center bg-gray-50 rounded-b-2xl">
            <p className="text-xs text-gray-600">
              Click on the marker for coordinates
            </p>
            <button
              onClick={() => setShowExpanded(false)}
              className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg transition-colors"
            >
              Close Map
            </button>
          </div>
        </div>
      </>
    );
  }

  // Mini map view
  return (
    <div className="w-full space-y-2">
      <div className={`relative rounded-xl overflow-hidden border-2 border-gray-200 shadow-md bg-gray-100 ${containerHeight}`}>
        <MapContent />

        {/* Expand Button */}
        <button
          onClick={() => setShowExpanded(true)}
          className="absolute bottom-3 right-3 bg-white hover:bg-blue-50 border-2 border-gray-200 hover:border-blue-500 text-gray-700 hover:text-blue-600 font-semibold py-2 px-3 rounded-lg transition-all duration-200 shadow-md hover:shadow-lg flex items-center gap-2 z-10"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6v4m12-4h4v4M10 18H6v-4m12 4h4v-4" />
          </svg>
          <span className="text-xs">Expand</span>
        </button>
      </div>

      {/* Coordinate Badge */}
      <div className="flex items-center gap-2 text-xs bg-blue-50 border border-blue-200 rounded-lg p-2">
        <svg className="w-4 h-4 text-blue-600 flex-shrink-0" fill="currentColor" viewBox="0 0 24 24">
          <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8z" />
        </svg>
        <span className="text-gray-700">
          <span className="font-semibold text-blue-600">{lat.toFixed(4)}, {lng.toFixed(4)}</span> • {area || 'Unknown'}
        </span>
      </div>
    </div>
  );
};

export default LocationMap;
